import unittest
from candidate import encode_cyclic, decode_cyclic

class TestCyclicOperations(unittest.TestCase):
    def test_encode_cyclic_normal_case(self):
        self.assertEqual(encode_cyclic("abcdefgh"), "bcaefdgh")

    def test_encode_cyclic_empty_string(self):
        self.assertEqual(encode_cyclic(""), "")

    def test_encode_cyclic_single_character(self):
        self.assertEqual(encode_cyclic("a"), "a")

    def test_encode_cyclic_two_characters(self):
        self.assertEqual(encode_cyclic("ab"), "ab")

    def test_encode_cyclic_three_characters(self):
        self.assertEqual(encode_cyclic("abc"), "bca")

    def test_encode_cyclic_four_characters(self):
        self.assertEqual(encode_cyclic("abcd"), "bcad")

    def test_encode_cyclic_five_characters(self):
        self.assertEqual(encode_cyclic("abcde"), "bcaed")

    def test_encode_cyclic_non_string_input(self):
        with self.assertRaises(TypeError):
            encode_cyclic(123)

    def test_decode_cyclic_normal_case(self):
        self.assertEqual(decode_cyclic("bcaefdgh"), "abcdefgh")

    def test_decode_cyclic_empty_string(self):
        self.assertEqual(decode_cyclic(""), "")

    def test_decode_cyclic_single_character(self):
        self.assertEqual(decode_cyclic("a"), "a")

    def test_decode_cyclic_two_characters(self):
        self.assertEqual(decode_cyclic("ab"), "ab")

    def test_decode_cyclic_three_characters(self):
        self.assertEqual(decode_cyclic("bca"), "abc")

    def test_decode_cyclic_four_characters(self):
        self.assertEqual(decode_cyclic("bcad"), "abcd")

    def test_decode_cyclic_five_characters(self):
        self.assertEqual(decode_cyclic("bcaed"), "abcde")

    def test_decode_cyclic_non_string_input(self):
        with self.assertRaises(TypeError):
            decode_cyclic(123)

if __name__ == '__main__':
    unittest.main()
